// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAccessTokens The book's personal access tokens for MCP, newest first, without their text.
	// (GET /access-tokens)
	ListAccessTokens(ctx context.Context, request ListAccessTokensRequestObject) (ListAccessTokensResponseObject, error)
	// CreateAccessToken Create a personal access token that opens /mcp only; the answer holds its text once.
	// (POST /access-tokens)
	CreateAccessToken(ctx context.Context, request CreateAccessTokenRequestObject) (CreateAccessTokenResponseObject, error)
	// DeleteAccessToken Delete a personal access token; it stops working at once.
	// (DELETE /access-tokens/{id})
	DeleteAccessToken(ctx context.Context, request DeleteAccessTokenRequestObject) (DeleteAccessTokenResponseObject, error)
	// CreateBooks Create a book with the member as owner; the session stays in its book (HA6).
	// (POST /books)
	CreateBooks(ctx context.Context, request CreateBooksRequestObject) (CreateBooksResponseObject, error)
	// GetCurrentBooks Return the settings of the active book (ADR 029 BK22).
	// (GET /books/current)
	GetCurrentBooks(ctx context.Context, request GetCurrentBooksRequestObject) (GetCurrentBooksResponseObject, error)
	// UpdateCurrentBooks Change the name, the region and the time zone of the active book.
	// (PATCH /books/current)
	UpdateCurrentBooks(ctx context.Context, request UpdateCurrentBooksRequestObject) (UpdateCurrentBooksResponseObject, error)
	// ListInvitations List the pending invitations of the active book, without tokens (HA24).
	// (GET /books/current/invitations)
	ListInvitations(ctx context.Context, request ListInvitationsRequestObject) (ListInvitationsResponseObject, error)
	// CreateInvitation Invite an email to the active book; the answer holds the token once (HA24).
	// (POST /books/current/invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)
	// DeleteInvitation Revoke a pending invitation of the active book.
	// (DELETE /books/current/invitations/{id})
	DeleteInvitation(ctx context.Context, request DeleteInvitationRequestObject) (DeleteInvitationResponseObject, error)
	// ListMembers List the memberships of the active book (HA19).
	// (GET /books/current/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// RemoveMember Remove a membership of the active book with its sessions, access tokens and conversations (HA20, HA22).
	// (DELETE /books/current/members/{memberId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// UpdateMember Change the role of a membership of the active book (HA20).
	// (PATCH /books/current/members/{memberId})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// LeaveBooks Remove the caller's membership of the active book; the session ends with it (HA20).
	// (DELETE /books/current/membership)
	LeaveBooks(ctx context.Context, request LeaveBooksRequestObject) (LeaveBooksResponseObject, error)
	// AcceptInvitation Accept an invitation (HA26).
	// (POST /invitations/accept)
	AcceptInvitation(ctx context.Context, request AcceptInvitationRequestObject) (AcceptInvitationResponseObject, error)
	// PreviewInvitation Describe the invitation of a token (HA25).
	// (POST /invitations/preview)
	PreviewInvitation(ctx context.Context, request PreviewInvitationRequestObject) (PreviewInvitationResponseObject, error)
	// GetCurrentUser Return the authenticated member.
	// (GET /me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// UpdateCurrentUser Change the language of the authenticated member.
	// (PATCH /me)
	UpdateCurrentUser(ctx context.Context, request UpdateCurrentUserRequestObject) (UpdateCurrentUserResponseObject, error)
	// GetMemberAppearance Return the appearance choices of the authenticated member (ADR 029 BK21).
	// (GET /me/appearance)
	GetMemberAppearance(ctx context.Context, request GetMemberAppearanceRequestObject) (GetMemberAppearanceResponseObject, error)
	// SetMemberAppearance Replace the appearance choices of the authenticated member.
	// (PUT /me/appearance)
	SetMemberAppearance(ctx context.Context, request SetMemberAppearanceRequestObject) (SetMemberAppearanceResponseObject, error)
	// ListMyBooks List the books of the member's memberships (HA5).
	// (GET /me/books)
	ListMyBooks(ctx context.Context, request ListMyBooksRequestObject) (ListMyBooksResponseObject, error)
	// CreatePasskey Register a passkey on the host of the request (HA41 to HA44).
	// (POST /me/passkeys)
	CreatePasskey(ctx context.Context, request CreatePasskeyRequestObject) (CreatePasskeyResponseObject, error)
	// CreatePasskeyOptions Start a passkey registration; the challenge lasts 5 minutes (HA44).
	// (POST /me/passkeys/options)
	CreatePasskeyOptions(ctx context.Context, request CreatePasskeyOptionsRequestObject) (CreatePasskeyOptionsResponseObject, error)
	// RemovePasskey Delete a passkey; the recovery codes go with the last factor (HA44, HA37).
	// (POST /me/passkeys/{id}/remove)
	RemovePasskey(ctx context.Context, request RemovePasskeyRequestObject) (RemovePasskeyResponseObject, error)
	// RegenerateRecoveryCodes Replace every recovery code; the answer holds them once (HA37).
	// (POST /me/recovery-codes)
	RegenerateRecoveryCodes(ctx context.Context, request RegenerateRecoveryCodesRequestObject) (RegenerateRecoveryCodesResponseObject, error)
	// GetSecondFactor The member's second factors (HA39).
	// (GET /me/second-factor)
	GetSecondFactor(ctx context.Context, request GetSecondFactorRequestObject) (GetSecondFactorResponseObject, error)
	// StartTotp Store a new unconfirmed TOTP secret and return it once (HA35).
	// (POST /me/totp)
	StartTotp(ctx context.Context, request StartTotpRequestObject) (StartTotpResponseObject, error)
	// ConfirmTotp Confirm the TOTP secret with a code of the app (HA35, HA37).
	// (POST /me/totp/confirm)
	ConfirmTotp(ctx context.Context, request ConfirmTotpRequestObject) (ConfirmTotpResponseObject, error)
	// DisableTotp Delete the TOTP secret; the recovery codes go with the last factor (HA35, HA37).
	// (POST /me/totp/disable)
	DisableTotp(ctx context.Context, request DisableTotpRequestObject) (DisableTotpResponseObject, error)
	// DeleteSession Log out and end the current session.
	// (DELETE /session)
	DeleteSession(ctx context.Context, request DeleteSessionRequestObject) (DeleteSessionResponseObject, error)
	// CreateSession Log in; a member with a second factor receives 202 and finishes with completeSecondFactor (HA46).
	// (POST /session)
	CreateSession(ctx context.Context, request CreateSessionRequestObject) (CreateSessionResponseObject, error)
	// SwitchBooks Move the current session to another book of the member (HA4).
	// (PUT /session/books)
	SwitchBooks(ctx context.Context, request SwitchBooksRequestObject) (SwitchBooksResponseObject, error)
	// CompleteSecondFactor Finish a pending login with a second factor (HA47).
	// (POST /session/second-factor)
	CompleteSecondFactor(ctx context.Context, request CompleteSecondFactorRequestObject) (CompleteSecondFactorResponseObject, error)
	// GetSetup Report whether the first member is still to be created (ADR 003, amendment of 2026-10-27).
	// (GET /setup)
	GetSetup(ctx context.Context, request GetSetupRequestObject) (GetSetupResponseObject, error)
	// CompleteSetup Create the first member, an admin, with the setup token, and start a session.
	// (POST /setup)
	CompleteSetup(ctx context.Context, request CompleteSetupRequestObject) (CompleteSetupResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListAccessTokens operation middleware
func (sh *strictHandler) ListAccessTokens(w http.ResponseWriter, r *http.Request) {
	var request ListAccessTokensRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListAccessTokens(ctx, request.(ListAccessTokensRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListAccessTokens")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListAccessTokensResponseObject); ok {
		if err := validResponse.VisitListAccessTokensResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

